"""Legacy-compatible Meridian CRM RBAC permission check."""


def can(
    user: dict,
    action: str,
    object: str,
    record: dict,
    role_rows: list[dict],
) -> bool:
    """Return whether the user may perform action on object and record."""
    role_id = user.get("ROLE_ID", "")

    for row in role_rows:
        if (
            row.get("role_id", "") != role_id
            or row.get("object", "") != object
            or row.get("action", "") != action
        ):
            continue

        if action == "DELETE":
            del_flg = record.get("DEL_FLG", "")
            if del_flg == "":
                del_flg = "N"
            if del_flg != "N":
                return False

        if role_id == "ADMIN":
            return True

        scope = row.get("scope", "")
        if scope == "ALL":
            return True
        if scope == "TEAM":
            return user.get("TEAM_CD", "") == record.get("TEAM_CD", "")
        if scope == "OWN":
            return record.get("OWNER_UID", "") == user.get("USR_ID", "")
        return False

    return False
